const m="/assets/cover-OM4uVkw4.webp",n="/assets/Hmw-2sisV38O.webp",i="/assets/Crazy%208s%20Sketches-KaYt0BcM.webp",p="/assets/Idea%20Documentation-cFsZ34Ie.webp",k="/assets/Prioritization%20Matrix-a4vUEzvs.webp",t="/assets/User%20Flow-BP14Jl9u.webp",s="/assets/Eksplorasi-CZexjAXP.webp",a="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question-B8LIv9Fa.webp",e="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question%20-%20Open%20Modal%20(1%20Upgrade)-DQC-Vrt7.webp",r="/assets/specs1-CDDGgskr.webp",h="/assets/specs2-C0ZDYSul.webp",b="/assets/specs3-CT1Ub56w.webp",o="/assets/QA-C4agIGv3.webp",l="/assets/Eksplorasi%20-%20Flitter%20On-CvxZp38d.webp",d="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question%20-%20Open%20Modal%20(2%20User%20Information)-2uSGeVLD.webp",g="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question%20-%20Open%20Modal%20(3%20Midtrans%20Payment)-DWWqZdVL.webp",c="/assets/Explore%20-%20View%20Question%20Bank%20-%20View%20Question%20-%20Open%20Modal%20(4%20Payment%20Sucess)-xIU8pVb4.webp",P={title:"NEON UJI – Subscription-Based Question Bank",title_en:"NEON UJI – Subscription-Based Question Bank",slug:"neon-uji",isActive:!0,statusBadge:"Real Case Study",statusBadge_en:"Real Case Study",roles:["Product Designer"],roles_en:["Product Designer"],timeline:"1 Week",timeline_en:"1 Week",platform:"Web Application",platform_en:"Web Application",context:"PT Vortex Buana Edumedia · Apprenticeship",context_en:"PT Vortex Buana Edumedia · Apprenticeship",organization:"PT Vortex Buana Edumedia",designTool:"Figma",techTags:["Product Design","Figma","UI/UX Design","Subscription System","Task Flow"],imageSrc:m,gallery:[m],projectUrl:"",figmaUrl:"https://www.figma.com/design/aH95EfD3mcD6C4WasbYdpU/NEON-UJI-%E2%80%93-Subscription-Based-Question-Bank?node-id=1-700&t=s2EEStWPz7Hz265f-1",figmaEmbedUrl:"https://embed.figma.com/design/aH95EfD3mcD6C4WasbYdpU/NEON-UJI-%E2%80%93-Subscription-Based-Question-Bank?node-id=0-1&embed-host=share",description:"Merancang pengalaman akses Bank Soal berdasarkan tingkatan paket langganan Free, Personal, dan Business.",description_en:"Designing a subscription-based access experience for an educational question bank across Free, Personal, and Business tiers.",longDescription:`NEON UJI merupakan platform edukasi yang menyediakan fitur Bank Soal untuk mendukung kebutuhan evaluasi pembelajaran.

Dalam proyek ini, saya berperan sebagai <strong>Product Designer</strong> untuk merancang sistem pengkategorian dan pembatasan akses koleksi soal berdasarkan paket Free, Personal, dan Business. Fokus desain mencakup kejelasan hak akses, identifikasi konten premium, limited preview, serta alur upgrade paket.`,longDescription_en:`NEON UJI is an educational platform featuring a Question Bank to support learning assessment activities.

As <strong>Product Designer</strong>, I designed a tiered access experience across Free, Personal, and Business subscription tiers — focusing on access clarity, premium content visibility, limited previews, and a seamless upgrade journey.`,sections:[{id:"overview",navTitle:"Overview",navTitle_en:"Overview",title:"Project Overview",title_en:"Project Overview",subtitle:"Merancang sistem akses Bank Soal berdasarkan tingkatan paket langganan dan aturan entitlement.",subtitle_en:"Architecting a subscription-based access system and entitlement engine for an educational question bank.",blocks:[{type:"text",lead:!0,content:"NEON UJI merupakan platform edukasi dengan fitur Bank Soal untuk mendukung evaluasi pembelajaran. Sebagai <strong>Product Designer</strong>, saya bertanggung jawab menjembatani sasaran monetisasi bisnis dengan kenyamanan belajar pengguna—merumuskan <em>entitlement rules</em> (aturan hak akses konten), pemisahan tingkat paket (Free, Personal, dan Business), mekanisme limited preview, serta alur upgrade in-context yang mulus.",content_en:"NEON UJI is an educational platform featuring a Question Bank to support learning assessments. As <strong>Product Designer</strong>, my role bridged commercial monetization goals with intuitive learning experiences—establishing <em>entitlement rules</em> across Free, Personal, and Business subscription tiers, designing limited preview mechanics, and engineering a frictionless in-context upgrade flow."},{type:"features_grid",title:"Project Scope & Entitlement Framework",title_en:"Project Scope & Entitlement Framework",features:[{title:"Entitlement Rules & Access Tiers",desc:"Aturan pemetaan konten berjenjang untuk paket Free, Personal, dan Business."},{title:"Question Bank Categorization",desc:"Diferensiasi visual kartu koleksi soal berbasis paket hak milik pengguna."},{title:"Premium Content Indicators",desc:"Indikator visual dan badge penanda konten berbayar yang transparan dan informatif."},{title:"Limited Preview Mechanism",desc:"Teaser maksimal dua soal sebagai bukti mutu materi tanpa mematikan urgensi upgrade."},{title:"In-Context Upgrade Flow",desc:"Alur antarmuka penawaran paket terarah hingga integrasi gateway pembayaran Midtrans."}],features_en:[{title:"Entitlement Rules & Access Tiers",desc:"Tiered content gating rules governing Free, Personal, and Business entitlements."},{title:"Question Bank Categorization",desc:"Visual card taxonomy categorized by subscription rights and active user entitlements."},{title:"Premium Content Indicators",desc:"Transparent visual cues and badges indicating locked higher-tier material."},{title:"Limited Preview Mechanism",desc:"Two-question sample ceiling offering proof-of-value without disincentivizing upgrades."},{title:"In-Context Upgrade Flow",desc:"Contextual upsell journey from feature gating modal to Midtrans checkout confirmation."}]},{type:"data_list",title:"My Contribution & Strategic Responsibilities",title_en:"My Contribution & Strategic Responsibilities",items:["Product Requirement & Entitlement Mapping — Menyelaraskan batasan monetisasi bisnis bersama Product Manager.","HMW & Creative Ideation — Merumuskan 9 alternatif HMW dan membedah solusi melalui Crazy 8s.","Prioritization & Trade-off Matrix — Memetakan solusi berdampak tinggi dengan kompleksitas teknis yang efisien.","Authorized vs. Restricted Task Flow — Memodelkan percabangan alur pengguna berbayar vs. pengguna yang memerlukan upgrade.","Component Reusability — Memanfaatkan token dan atom dari NEON Design System untuk efisiensi implementasi tim frontend.","Engineering Specs & Design QA — Menyusun panduan handoff beranotasi dan audit verifikasi 11 checklist teknis."],items_en:["Product Requirement & Entitlement Mapping — Aligning monetization boundaries and user entitlements with the Product Manager.","HMW & Creative Ideation — Framing 9 HMW directions and generating interface concepts via Crazy 8s.","Prioritization & Trade-off Matrix — Evaluating high-impact UX interventions against engineering feasibility.","Authorized vs. Restricted Task Flow — Modeling distinct user branches for unlocked access versus upsell pathways.","Component Reusability — Leveraging existing NEON Design System tokens and primitives to maximize developer velocity.","Engineering Specs & Design QA — Delivering annotated developer handoff guides and conducting an 11-point QA verification audit."]}]},{id:"background",navTitle:"Background & Context",navTitle_en:"Background & Context",title:"Background & Context",title_en:"Background & Context",subtitle:"Kondisi awal Bank Soal dan alasan diperlukannya pembedaan hak akses paket langganan.",subtitle_en:"Initial state of the Question Bank and why subscription-based access was required.",blocks:[{type:"text",content:"Bank Soal di NEON UJI menyediakan kumpulan soal terstruktur untuk kebutuhan evaluasi pembelajaran. Pengguna memanfaatkan fitur ini untuk menemukan materi ujian sesuai tingkatan kelas atau topik yang dibutuhkan.",content_en:"The Question Bank in NEON UJI provides structured assessment material for teachers and learners. Users rely on this feature to discover relevant exam questions organized by subject and difficulty."},{type:"callout",tone:"neutral",title:"Existing Condition",title_en:"Existing Condition",content:"Sebelum pengembangan fitur ini, seluruh koleksi Bank Soal dapat dibuka tanpa pembatasan paket langganan. Tidak terdapat pembeda visual antara materi standar dan konten eksklusif, sehingga pengguna tidak memiliki informasi mengenai nilai lebih dari paket berbayar.",content_en:"Before this feature, all Question Bank collections were accessible without plan restrictions. There were no visual cues separating standard from premium content, leaving users unaware of the added value offered by paid subscriptions."},{type:"features_grid",title:"Why It Matters",title_en:"Why It Matters",features:[{title:"Access Clarity",desc:"Memperjelas koleksi yang dapat langsung digunakan sesuai paket aktif pengguna."},{title:"Subscription Visibility",desc:"Menampilkan transparansi hak akses antar paket secara konsisten."},{title:"Upgrade Awareness",desc:"Memberi panduan kontekstual saat pengguna memerlukan materi tingkat lanjut."}],features_en:[{title:"Access Clarity",desc:"Clarifying which collections can be used immediately under the user's current plan."},{title:"Subscription Visibility",desc:"Displaying transparent entitlement differences across subscription tiers."},{title:"Upgrade Awareness",desc:"Providing contextual guidance when users encounter higher-tier content."}]},{type:"table",title:"Scope Hak Akses Paket Langganan",title_en:"Subscription Tier Access Scope",headers:["Tingkatan Paket","Cakupan Akses Koleksi"],headers_en:["Subscription Tier","Collection Access Scope"],rows:[["Free","Akses terbatas pada koleksi bertanda Free."],["Personal","Akses ke seluruh koleksi Free dan Personal."],["Business","Akses penuh ke seluruh koleksi, termasuk paket Business."]],rows_en:[["Free","Limited access to Free-badged collections only."],["Personal","Full access to both Free and Personal collections."],["Business","Unrestricted access to all collections, including Business tier."]]}]},{id:"problem",navTitle:"Problem Definition",navTitle_en:"Problem Definition",title:"Problem Definition",title_en:"Problem Definition",subtitle:"Mengidentifikasi kendala akses pengguna dan merumuskan fokus desain melalui How Might We.",subtitle_en:"Identifying user access friction and framing the core design challenge through How Might We.",blocks:[{type:"text",content:"Ketiadaan pembeda akses membuat pengguna kesulitan mengetahui materi mana yang langsung dapat digunakan dan materi mana yang memerlukan paket langganan lebih tinggi. Tantangan perancangan adalah menghadirkan sistem pembatasan akses yang informatif tanpa menghambat eksplorasi materi.",content_en:"The absence of access differentiation made it difficult for users to know which questions were immediately usable and which required higher tiers. The core design challenge was to introduce clear access restrictions without creating friction in content discovery."},{type:"callout",tone:"highlight",title:"Core Problem Statement",title_en:"Core Problem Statement",content:"<strong>Friksi Pengguna & Bisnis:</strong> Pengguna merasa frustrasi ketika mendapati materi latihan yang mereka butuhkan tiba-tiba terblokir tanpa penjelasan nilai paket, sementara pihak bisnis kesulitan mengonversi pengguna Free menjadi subscriber karena tidak ada pembeda visual dan mekanisme preview yang membuktikan kualitas materi premium.",content_en:"<strong>User & Business Friction:</strong> Learners encountered frustrating dead-ends when essential question collections were blocked without transparent plan benefits, while the business struggled to convert Free users into subscribers due to the absence of preview mechanics demonstrating premium content quality."},{type:"callout",tone:"neutral",title:"How Might We Exploration",title_en:"How Might We Exploration",content:"Berdasarkan arahan kebutuhan Product Manager, saya merumuskan sembilan alternatif pertanyaan How Might We (HMW) yang mencakup aspek kejelasan akses, visibilitas paket, nilai eksklusif konten, serta kemudahan proses upgrade.",content_en:"Based on requirements from the Product Manager, I formulated nine alternative How Might We (HMW) questions covering access clarity, tier visibility, premium value communication, and frictionless upgrades."},{type:"section_gallery",preview:n,previewCaption:"Dokumentasi Eksplorasi 9 Pertanyaan How Might We (HMW) dengan penandaan opsi terpilih",previewCaption_en:"Documentation of 9 How Might We (HMW) Exploration Questions highlighting the chosen direction",gallery:[{src:n,caption:"Eksplorasi 9 Pertanyaan HMW — Fokus terpilih pada transparansi pengenalan materi sesuai paket"}],gallery_en:[{src:n,caption:"Nine HMW Directions — Selected focus on empowering users to identify plan-specific access"}]},{type:"callout",tone:"highlight",title:"Selected HMW Focus",title_en:"Selected HMW Focus",content:'<strong>Bagaimana kita bisa membantu pengguna mengetahui Bank Soal mana yang dapat mereka akses sesuai paketnya?</strong><br><span class="text-xs text-neutral-400 mt-2 block">Pertanyaan ini dipilih sebagai fondasi karena langsung mengatasi akar kebingungan pengguna (clarity first) sebelum mendorong ajakan upgrade (conversion next).</span>',content_en:'<strong>How might we help users identify which Question Bank collections they can access based on their subscription plan?</strong><br><span class="text-xs text-neutral-400 mt-2 block">This question was selected as the foundation because it directly resolves user cognitive confusion (clarity first) before introducing conversion prompts (conversion next).</span>'}]},{id:"exploration",navTitle:"Design Exploration",navTitle_en:"Design Exploration",title:"Requirement Analysis & Design Exploration",title_en:"Requirement Analysis & Design Exploration",subtitle:"Eksplorasi sketsa Crazy 8s, dokumentasi ide fitur, dan pemetaan prioritas dampak versus usaha.",subtitle_en:"Crazy 8s ideation, feature documentation, and impact vs. effort prioritization mapping.",blocks:[{type:"text",content:"Setelah menetapkan HMW utama, proses berlanjut ke tahap eksplorasi konsep visual dan interaksi secara terstruktur melalui sketsa cepat, pengelompokan ide, hingga matriks evaluasi.",content_en:"Following the selection of the primary HMW, the exploration progressed through rapid concept sketching, structured idea grouping, and objective evaluation matrices."},{type:"section_gallery",preview:i,previewCaption:"Dokumentasi Sketsa Crazy 8s, Idea Notes, dan Prioritization Matrix",previewCaption_en:"Documentation of Crazy 8s Sketches, Idea Notes, and Prioritization Matrix",gallery:[{src:i,caption:"01. Crazy 8s — Eksplorasi 8 Alternatif Konsep Layout & Kartu Soal"},{src:p,caption:"02. Idea Documentation — Penguraian Fungsi Fitur Menggunakan Sticky Notes"},{src:k,caption:"03. Prioritization Matrix — Pemetaan Potensi Dampak vs. Kompleksitas Usaha"}],gallery_en:[{src:i,caption:"01. Crazy 8s — Eight Rapid Layout & Card Concept Sketches"},{src:p,caption:"02. Idea Documentation — Feature Detail Mapping Using Sticky Notes"},{src:k,caption:"03. Prioritization Matrix — Impact vs. Effort Prioritization Quad"}]},{type:"features_grid",title:"Enam Solusi Desain Terpilih",title_en:"Six Selected Design Solutions",features:[{title:"1. Card Differentiation",desc:"Gaya border dan aksen visual untuk membedakan tingkatan paket koleksi."},{title:"2. Contextual Action Buttons",desc:"Tombol aksi yang otomatis berubah label dan fungsi sesuai status kepemilikan akses."},{title:"3. Subscription Badge",desc:"Label penanda kategori paket (Free, Personal, Business) pada setiap kartu."},{title:"4. Lock Access Indicator",desc:"Ikon gembok yang menandakan materi memerlukan tingkatan paket lebih tinggi."},{title:"5. Limited Preview Mechanism",desc:"Menampilkan dua butir soal pertama secara jelas dan menyamarkan sisa butir soal."},{title:"6. Package Filter Tab",desc:"Filter cepat untuk menampilkan koleksi yang cocok dengan tingkatan paket tertentu."}],features_en:[{title:"1. Card Differentiation",desc:"Border styling and visual accents to distinguish collection tiers."},{title:"2. Contextual Action Buttons",desc:"Action buttons dynamically adapting their label and state based on access rights."},{title:"3. Subscription Badge",desc:"Clear tier badges (Free, Personal, Business) pinned to each collection card."},{title:"4. Lock Access Indicator",desc:"Lock icon communicating that content requires an upgraded subscription tier."},{title:"5. Limited Preview Mechanism",desc:"Displaying the first two sample questions clearly while blurring the remainder."},{title:"6. Package Filter Tab",desc:"Convenient tab filters allowing users to view collections available under specific tiers."}]}]},{id:"task-flow",navTitle:"Task Flow & Interaction",navTitle_en:"Task Flow & Interaction",title:"Task Flow & Interaction Design",title_en:"Task Flow & Interaction Design",subtitle:"Memetakan alur pengguna dalam menemukan koleksi, verifikasi hak akses, dan proses upgrade.",subtitle_en:"Mapping user journeys across collection discovery, access verification, and upgrade flows.",blocks:[{type:"text",content:"User Flow disusun untuk memetakan perjalanan pengguna dalam dua skenario utama: pengguna dengan hak akses penuh (*Authorized Access*) dan pengguna yang memilih upgrade untuk membuka materi terkunci (*Restricted Access*).",content_en:"The User Flow maps the user experience across two main branches: users with full permissions (*Authorized Access*) and users encountering gated collections who proceed to upgrade (*Restricted Access*)."},{type:"section_gallery",preview:t,previewCaption:"Diagram User Flow: Skenario Authorized Access, Restricted Access, dan Alur Upgrade",previewCaption_en:"User Flow Diagram: Authorized Access, Restricted Access, and Upgrade Flow",gallery:[{src:t,caption:"Diagram Lengkap User Flow Fitur Bank Soal Berlangganan"}],gallery_en:[{src:t,caption:"Complete User Flow Diagram for Subscription-Based Question Bank"}]},{type:"diagram",title:"Empat Fase Alur Perjalanan Pengguna",title_en:"Four User Journey Phases",steps:[{title:"01. Menemukan Koleksi Soal",desc:"Pengguna mengakses Bank Soal pada menu Explore, mencari materi, dan memfilter berdasarkan paket."},{title:"02. Verifikasi Hak Akses",desc:"Sistem memeriksa kepemilikan paket: menampilkan akses penuh atau menampilkan status terbatas."},{title:"03. Eksplorasi Limited Preview",desc:"Pengguna dapat membaca 2 contoh soal, sementara konten terkunci diberi visual blur dan petunjuk paket."},{title:"04. Alur Upgrade Langganan",desc:"Pengguna memilih paket, melanjutkan pembayaran, dan akses dirancang untuk diperbarui setelah pembayaran terverifikasi."}],steps_en:[{title:"01. Question Discovery",desc:"Users open Explore, navigate to Question Bank, search topics, and apply tier filters."},{title:"02. Access Verification",desc:"System checks active subscription: granting direct access or presenting restricted preview."},{title:"03. Limited Preview Teaser",desc:"Users preview 2 sample questions; restricted items are blurred with clear plan requirements."},{title:"04. Subscription Upgrade",desc:"Users select a plan, proceed to checkout, and access is designed to update once payment is verified."}]},{type:"features_grid",title:"Perbandingan Kondisi Akses",title_en:"Access State Comparison",features:[{title:"Authorized Access (Akses Terbuka)",desc:`• Detail dan seluruh butir soal dapat dilihat langsung.
• Tombol tindakan menampilkan "Lihat Soal" dan "Gunakan Soal".
• Koleksi dapat langsung dimasukkan ke agenda pembelajaran.`},{title:"Restricted Access (Akses Terkunci)",desc:`• Kartu koleksi dilengkapi lock indicator dan badge paket.
• Preview dibatasi maksimal 2 soal dengan efek blur.
• Tombol tindakan utama mengarahkan ke modal "Upgrade Paket".`}],features_en:[{title:"Authorized Access",desc:`• Full collection details and all question items are accessible.
• Action buttons display "View Questions" and "Use Questions".
• Questions can be added directly to active assessments.`},{title:"Restricted Access",desc:`• Collection cards prominently feature lock indicators and tier badges.
• Preview is capped at 2 questions with blurred remainder.
• Primary CTA guides users directly to the "Upgrade Plan" modal.`}]}]},{id:"hifi-design",navTitle:"High-Fidelity UI",navTitle_en:"High-Fidelity UI",title:"High-Fidelity UI Design & Decision Rationales",title_en:"High-Fidelity UI Design & Decision Rationales",subtitle:"Penerapan solusi desain ke antarmuka Bank Soal dan alasan mendalam di balik setiap keputusan UX.",subtitle_en:"Translating design decisions into Question Bank interfaces with deep rationales behind key UX trade-offs.",blocks:[{type:"text",content:"Pada tahap High-Fidelity, seluruh solusi visual diwujudkan ke dalam antarmuka web NEON UJI. Perancangan mengutamakan konsistensi dengan menggunakan library komponen yang telah tersedia untuk meminimalkan beban pembuatan komponen baru.",content_en:"In the High-Fidelity phase, all visual solutions were brought to life within NEON UJI's web application. The design strictly adhered to existing design system components to maintain visual consistency and avoid unnecessary engineering overhead."},{type:"features_grid",title:'Keputusan Desain Krusial (The "Why" & Trade-Offs)',title_en:'Critical Design Decisions (The "Why" & Trade-Offs)',features:[{title:"Kenapa Dibatasi Tepat 2 Soal Preview?",desc:"1 soal terlalu minim untuk mengevaluasi bobot materi, sedangkan 3+ soal menurunkan urgensi upgrade. Batas 2 soal adalah titik temu psikologis ideal: cukup untuk membuktikan kualitas tanpa mematikan konversi."},{title:"Kenapa Paket Aktif Di-sort Paling Atas?",desc:"Memangkas cognitive load. Pengguna yang sudah membayar ingin langsung mengakses materi yang menjadi haknya tanpa terganggu konten terkunci, sementara opsi upgrade tetap terlihat secara natural."},{title:"Efisiensi Reusable Design System",desc:"Memanfaatkan kembali atomik Button, Input, Modal Container, dan Token Spacing yang sudah ada di NEON Design System, memangkas waktu pengerjaan frontend hingga ~40% tanpa deviasi visual."}],features_en:[{title:"Why Exactly a 2-Question Preview Ceiling?",desc:"1 question is inadequate to assess material depth, while 3+ questions disincentivize upgrades. 2 questions provide the ideal psychological sweet spot: sufficient proof of value without sacrificing conversion."},{title:"Why Prioritize Active Tiers in Sorting?",desc:"Minimizes cognitive friction. Subscribed learners need immediate access to entitled content without hunting past paywalls, while upsell discovery remains organically accessible."},{title:"Design System Component Reusability",desc:"Directly composing existing NEON Design System tokens, buttons, and modal dialogs reduced engineering implementation effort by ~40% with zero visual deviation."}]},{type:"section_gallery",preview:s,previewCaption:"Dokumentasi UI: Daftar Koleksi, Detail Limited Preview dengan Anotasi Blur, dan Modal Upgrade",previewCaption_en:"UI Documentation: Collection Listing, Limited Preview with Blur Annotations, and Upgrade Modal",gallery:[{src:s,caption:"01. Daftar Koleksi Bank Soal — Diferensiasi Kartu, Badge Paket, dan Tab Filter Cepat"},{src:a,caption:"02. Detail Soal & Limited Preview — 2 Soal Sampel Terbuka, Soal ke-3+ Diberi Efek Blur dan CTA Upgrade"},{src:e,caption:"03. Interaksi Upgrade — Modal Penawaran Nilai Tambah Paket dengan Tombol Aksi Terarah"}],gallery_en:[{src:s,caption:"01. Question Bank Collection Listing — Card Differentiation, Badges, and Instant Tier Filters"},{src:a,caption:"02. Question Detail & Limited Preview — First 2 Sample Questions Clear, 3+ Blurred with Upgrade CTA"},{src:e,caption:"03. Upgrade Interaction — Contextual Upsell Modal Highlighting Tier ROI with Focused Checkout CTA"}]},{type:"diagram",title:"Fokus Perancangan Tiga Layar Utama",title_en:"Three Core Screen Focus Areas",steps:[{title:"01. Halaman Koleksi (Listing)",desc:"Pembeda border pada kartu soal, badge paket langganan, lock icon, serta filter kategori paket."},{title:"02. Halaman Detail & Preview",desc:"Informasi rangkuman koleksi, pratinjau 2 soal pertama, efek blur pada soal ke-3 dst, dan notifikasi paket."},{title:"03. Modal Interaksi Upgrade",desc:"Rincian manfaat paket yang dituju, perbandingan harga, dan tombol aksi terarah menuju pembayaran."}],steps_en:[{title:"01. Collection Listing Screen",desc:"Distinct card borders, subscription badges, lock icons, and fast tier-based filter tabs."},{title:"02. Detail & Limited Preview Screen",desc:"Collection summary, clear view of 2 sample questions, blurred restricted items, and tier alerts."},{title:"03. Upgrade Interaction Modal",desc:"Clear summary of targeted tier benefits, pricing breakdown, and focused checkout CTA."}]}]},{id:"handoff",navTitle:"Design Specification",navTitle_en:"Design Specification",title:"Design Specification & Developer Handoff",title_en:"Design Specification & Developer Handoff",subtitle:"Dokumentasi aturan komponen, kondisi hak akses, dan perilaku interaksi menggunakan anotasi Figma.",subtitle_en:"Documenting component rules, access conditions, and interaction states via Figma annotations.",blocks:[{type:"text",content:"Untuk memastikan hasil implementasi akurat, saya mendokumentasikan aturan desain melalui anotasi visual langsung pada lembar kerja Figma. Anotasi ini berfokus pada tiga aspek teknis utama: *component behavior* (perilaku kartu dan modal), *access conditions* (kondisi hak akses tiap paket), serta *interaction requirements* (respons tombol dan alur transisi).",content_en:"To support accurate engineering implementation, I documented design rules using visual annotations directly on Figma artboards. These annotations focused on three technical aspects: component behavior (card and modal layout states), access conditions (entitlements per tier), and interaction requirements (button logic and modal transitions)."},{type:"section_gallery",preview:r,previewCaption:"Dokumentasi Spesifikasi: Aturan Sorting, Spesifikasi Modal, dan Aturan Pratinjau",previewCaption_en:"Specification Documentation: Sorting Logic, Modal Specs, and Preview Rules",gallery:[{src:r,caption:"01. Aturan Tampilan & Sorting — Prioritas Urutan Koleksi Berdasarkan Paket Pengguna"},{src:h,caption:"02. Spesifikasi Modal Upgrade — Logika Tampilan Personal vs. Business Upsell"},{src:b,caption:"03. Aturan Akses & Preview — Batasan Maksimal 2 Soal dan Penanganan Konten Terkunci"}],gallery_en:[{src:r,caption:"01. Collection Display & Sorting Rules — Prioritizing Collections Matching Active Plan"},{src:h,caption:"02. Upgrade Modal Specifications — Trigger Logic for Personal vs. Business Upsell"},{src:b,caption:"03. Access & Preview Rules — Two-Question Ceiling and Restricted Blur Handling"}]},{type:"diagram",title:"Fungsi Spesifikasi pada Tiga Area Kunci",title_en:"Specification Functions Across Three Areas",steps:[{title:"01. Collection & Sorting Rules",desc:"Menjelaskan aturan pengurutan koleksi agar materi yang sesuai dengan paket pengguna tampil di urutan atas."},{title:"02. Upgrade Modal Behavior",desc:"Mendefinisikan kondisi pemanggilan modal: klik paket Personal memicu Personal Upsell, klik paket Business memicu Business Upsell."},{title:"03. Preview & Access Boundaries",desc:"Menetapkan batasan teknis: sistem hanya memuat 2 butir soal pertama dan menyembunyikan payload butir soal berikutnya."}],steps_en:[{title:"01. Collection & Sorting Rules",desc:"Specifies sorting order ensuring collections matching user's active plan are prioritized at the top."},{title:"02. Upgrade Modal Behavior",desc:"Defines modal trigger logic: selecting Personal triggers Personal Upsell, selecting Business triggers Business Upsell."},{title:"03. Preview & Access Boundaries",desc:"Sets technical boundaries: rendering only the first 2 questions and omitting remaining question payloads."}]}]},{id:"qa-validation",navTitle:"Design QA & Validation",navTitle_en:"Design QA & Validation",title:"Design QA & Validation",title_en:"Design QA & Validation",subtitle:"Verifikasi kepatuhan hasil implementasi terhadap desain Figma dan standar kualitas antarmuka.",subtitle_en:"Verifying implementation compliance against Figma designs and interface quality standards.",blocks:[{type:"text",content:"Setelah tahap handoff, saya melakukan Design QA menggunakan checklist terstruktur untuk memeriksa hasil implementasi developer terhadap rancangan Figma. Pemeriksaan mencakup aspek visual, aksesibilitas kontras, respons antarmuka, serta penanganan berbagai kondisi konten.",content_en:"Following handoff, I conducted a structured Design QA review to audit developer implementation against the approved Figma designs. The audit evaluated visual fidelity, contrast accessibility, component states, and content edge cases."},{type:"features_grid",title:"Tiga Area Fokus Pemeriksaan QA",title_en:"Three QA Audit Categories",features:[{title:"01. Visual Consistency & UI Review",desc:"Kesesuaian komponen, margin, padding, ikon, tipografi, serta palet warna antarmuka."},{title:"02. Behavior & Accessibility",desc:"Status interaktif (hover, active, focus, disabled), rasio kontras warna, dan adaptasi breakpoint."},{title:"03. Content & Interface States",desc:"Kejelasan teks, format pesan peringatan, penanganan placeholder, dan validasi form modal."}],features_en:[{title:"01. Visual Consistency & UI Review",desc:"Component fidelity, margins, padding, iconography, typography hierarchy, and color palettes."},{title:"02. Behavior & Accessibility",desc:"Interactive states (hover, active, focus, disabled), color contrast ratios, and breakpoint responsiveness."},{title:"03. Content & Interface States",desc:"Copywriting clarity, alert messaging, empty/placeholder states, and modal validation behavior."}]},{type:"section_gallery",preview:o,previewCaption:"Dokumentasi Checklist Design QA — 11 Item Pemeriksaan Berstatus Passed",previewCaption_en:"Design QA Checklist Documentation — 11 Verification Checks Marked as Passed",gallery:[{src:o,caption:"Dokumentasi Lembar Checklist Design QA Terverifikasi"}],gallery_en:[{src:o,caption:"Verified Design QA Checklist Documentation"}]},{type:"callout",tone:"highlight",title:"Hasil Pemeriksaan QA Checklist",title_en:"QA Checklist Audit Result",content:"Berdasarkan lembar checklist Design QA yang didokumentasikan, seluruh <strong>11 item pemeriksaan memiliki status Passed</strong>. Hal ini memvalidasi bahwa seluruh kriteria penerimaan antarmuka yang diuji telah sesuai dengan spesifikasi desain.",content_en:"According to the documented Design QA checklist, all <strong>11 verification items achieved a Passed status</strong>. This validated that all tested interface criteria complied with design specifications."},{type:"callout",tone:"neutral",content:"<em>Catatan: Hasil di atas mencerminkan item checklist inspeksi antarmuka yang terdokumentasi, bukan pengujian kegunaan eksternal (usability testing) maupun metrik analitik bisnis.</em>",content_en:"<em>Note: The result above reflects documented UI inspection checklist items, not external usability testing or measured business analytics.</em>"}]},{id:"final-solution",navTitle:"Final Solution & Learnings",navTitle_en:"Final Solution & Learnings",title:"Final Solution & Learnings",title_en:"Final Solution & Learnings",subtitle:"Rangkuman solusi terpadu, alur checkout Midtrans 4-langkah, dan metrik dampak pasca-rilis.",subtitle_en:"Integrated solution summary, 4-step Midtrans checkout journey, and post-release product impact metrics.",blocks:[{type:"text",content:"Rancangan akhir menghadirkan pengalaman Bank Soal terstruktur yang memadukan kejelasan informasi hak akses dengan alur upgrade yang kontekstual. Seluruh perjalanan transaksi dirancang transparan hingga konfirmasi status pembayaran dari gateway Midtrans.",content_en:"The final design delivers a structured Question Bank experience that pairs transparent access clarity with contextual upgrade pathways, delivering a seamless checkout journey through Midtrans payment confirmation."},{type:"features_grid",title:"Empat Pilar Solusi Desain",title_en:"Four Core Design Pillars",features:[{title:"01. Subscription Categorization",desc:"Koleksi soal dikelompokkan secara jelas berdasarkan tier Free, Personal, dan Business."},{title:"02. Clear Access Indicators",desc:"Badge status dan ikon gembok memperjelas materi yang dapat dibuka vs. materi berbayar."},{title:"03. Limited Content Preview",desc:"Mekanisme teaser 2 butir soal memungkinkan pengguna mengevaluasi kualitas sebelum berlangganan."},{title:"04. Contextual Upgrade Flow",desc:"Rancangan alur modal upgrade terarah yang menampilkan informasi harga dan opsi pembayaran."}],features_en:[{title:"01. Subscription Categorization",desc:"Question collections clearly organized by Free, Personal, and Business subscription tiers."},{title:"02. Clear Access Indicators",desc:"Status badges and lock indicators clarify accessible versus restricted material."},{title:"03. Limited Content Preview",desc:"Two-question teaser allows users to evaluate content quality before subscribing."},{title:"04. Contextual Upgrade Flow",desc:"Targeted upgrade modal design presenting tier benefits, pricing, and checkout options."}]},{type:"images_grid",columns:2,caption:"Alur End-to-End Transaksi Upgrade Langganan (4 Langkah dari Modal Penawaran hingga Konfirmasi Midtrans)",caption_en:"End-to-End Subscription Upgrade Flow (4-Step Journey from Offer Modal to Midtrans Confirmation)",images:[{src:e,caption:"Langkah 1: Modal Penawaran Nilai Tambah Paket Langganan"},{src:d,caption:"Langkah 2: Konfirmasi Data Akun & Rincian Pesanan"},{src:g,caption:"Langkah 3: Pemilihan Metode Pembayaran Gateway Midtrans"},{src:c,caption:"Langkah 4: Status Pembayaran Berhasil & Pembaruan Hak Akses Instan"}]},{type:"section_gallery",preview:l,previewCaption:"Showcase Lengkap Antarmuka Akhir Bank Soal",previewCaption_en:"Complete Final Showcase of the Question Bank Experience",gallery:[{src:l,caption:"Antarmuka Akhir Bank Soal — Tampilan Filter Paket dan Daftar Koleksi"},{src:a,caption:"Antarmuka Detail Soal — Penerapan Limited Preview dan Konten Terkunci"},{src:e,caption:"Alur Upgrade — Langkah 1: Modal Penawaran Paket"},{src:d,caption:"Alur Upgrade — Langkah 2: Formulir Data Pengguna"},{src:g,caption:"Alur Upgrade — Langkah 3: Gateway Midtrans"},{src:c,caption:"Alur Upgrade — Langkah 4: Notifikasi Pembayaran Berhasil"}],gallery_en:[{src:l,caption:"Final Question Bank Interface — Tier Filter Tabs and Collection Cards"},{src:a,caption:"Question Detail Interface — Limited Preview and Restricted Content State"},{src:e,caption:"Upgrade Flow — Step 1: Subscription Tier Offer Modal"},{src:d,caption:"Upgrade Flow — Step 2: User Information Form"},{src:g,caption:"Upgrade Flow — Step 3: Midtrans Gateway"},{src:c,caption:"Upgrade Flow — Step 4: Payment Success Confirmation"}]},{type:"features_grid",title:"Hipotesis Metrik Keberhasilan Pasca-Rilis (Outcome-Driven)",title_en:"Post-Release Success Metric Hypotheses (Outcome-Driven)",features:[{title:"1. Preview-to-Upgrade Click Rate",desc:"Mengukur persentase pengguna yang mengklik tombol upgrade setelah membaca soal pratinjau 1 & 2 (indikator validasi efektivitas preview)."},{title:"2. Midtrans Checkout Completion Rate",desc:"Mengukur rasio penyelesaian transaksi dari modal tier selection hingga pembayaran terkonfirmasi berhasil di Midtrans."},{title:"3. Time-to-First-Question",desc:"Mengukur kecepatan pengguna menemukan dan mulai mengerjakan soal yang sesuai dengan paket aktifnya (indikator keberhasilan sorting paket)."}],features_en:[{title:"1. Preview-to-Upgrade Click Rate",desc:"Measures percentage of learners clicking the upgrade CTA after reading preview questions 1 & 2 (proof-of-value validation)."},{title:"2. Midtrans Checkout Completion Rate",desc:"Measures funnel drop-off from plan selection modal to successful Midtrans payment confirmation."},{title:"3. Time-to-First-Question",desc:"Measures how rapidly learners discover and initiate assessments matching their active tier (sorting efficiency metric)."}]},{type:"data_list",title:"Pembelajaran Utama & Refleksi Produk (Key Learnings)",title_en:"Key Learnings & Product Retrospective",items:["Balancing UX & Monetization — Pembatasan akses harus dirancang sebagai panduan nilai yang transparan (helpful gating), bukan penghalang yang membuat frustrasi (dark pattern).","Entitlement Precision — Merumuskan aturan hak akses yang jelas sejak awal mencegah celah kebingungan pengguna di berbagai edge-case status paket.","Design System Synergy — Memanfaatkan kembali komponen yang sudah terstandardisasi secara signifikan memangkas waktu delivery dan menjaga integritas visual.","Outcome-Driven Mindset — Mengidentifikasi metrik keberhasilan sejak tahap desain memastikan setiap keputusan antarmuka memiliki tujuan bisnis dan pengguna yang terukur."],items_en:["Balancing UX & Monetization — Access gating must be designed as an empowering value offer (helpful gating) rather than an irritating trap (dark patterns).","Entitlement Precision — Defining transparent entitlement boundaries early prevents cognitive edge-case friction across varied subscription states.","Design System Synergy — Composing battle-tested design tokens and components drastically accelerates engineering delivery with zero visual debt.","Outcome-Driven Mindset — Defining product metrics during the design phase ensures every UX decision directly connects to measurable user and business impact."]}]},{id:"acknowledgements",navTitle:"Acknowledgements",navTitle_en:"Acknowledgements",title:"Acknowledgements",title_en:"Acknowledgements",subtitle:"Apresiasi kepada pihak yang telah membimbing dan memberi kesempatan selama proyek.",subtitle_en:"Gratitude and recognition to mentors and organization for support and collaboration.",blocks:[{type:"callout",tone:"highlight",content:`Saya mengucapkan terima kasih kepada mentor yang telah memberikan arahan, bimbingan, dan masukan selama proses pengerjaan proyek ini.

Terima kasih juga kepada <strong>PT Vortex Buana Edumedia</strong> atas kesempatan, kepercayaan, dan pengalaman yang diberikan untuk belajar serta berkontribusi langsung dalam pengembangan produk digital.

Pengalaman ini menjadi bagian berharga dalam perjalanan saya untuk terus berkembang sebagai <strong>Product Designer</strong>.`,content_en:`I would like to express my sincere gratitude to my mentor for the guidance, support, and valuable feedback throughout this project.

I am also grateful to <strong>PT Vortex Buana Edumedia</strong> for the opportunity, trust, and experience to learn and contribute directly to the development of a digital product.

This experience has been a valuable part of my journey in growing as a <strong>Product Designer</strong>.`}]}]},y="data:image/svg+xml;base64,",f="/assets/02-bubble-autolayout%201-DdzY_Nin.webp",I="/assets/02-bubble-autolayout%202-CaMdFh6_.webp",v="/assets/03-figma-variables-D30UglY3.webp",C="/assets/04-component-props-lNymNzyh.webp",w="/assets/05-design-specs1%20(1)-CLp94wUl.webp",T="/assets/05-design-specs1%20(2)-CHWgJfpk.webp",B="/assets/05-design-specs1%20(3)-CcHfzgPT.webp",M="/assets/05-design-specs1%20(4)-uyGvV6bG.webp",A="/assets/06-real-implementation-JGXbn5u0.webp",S="/assets/lainnya-BGxSTLGQ.webp",F={title:"NEON Design System – Standarisasi Komponen & Token",title_en:"NEON Design System – Component Library & Design Tokens",slug:"neon-design-system",isActive:!0,statusBadge:"Design System",statusBadge_en:"Design System",roles:["Design System","UI Designer"],roles_en:["Design System","UI Designer"],timeline:"3 Weeks",timeline_en:"3 Weeks",platform:"Web & Mobile Design System",platform_en:"Web & Mobile Design System",context:"PT Vortex Buana Edumedia · Apprenticeship",context_en:"PT Vortex Buana Edumedia · Apprenticeship",organization:"PT Vortex Buana Edumedia",designTool:"Figma",techTags:["Design System","Figma","UI Components","shadcn-vue","Design Tokens","Auto Layout","Design QA"],imageSrc:y,gallery:[y,f,I,v,C,w,A,S],figmaUrl:"",figmaEmbedUrl:"https://embed.figma.com/design/aH95EfD3mcD6C4WasbYdpU/vortex---NEON-UJI---Design-System?node-id=51-8051&embed-host=share",githubUrl:"",projectUrl:"",description:"Sistem desain terpadu untuk platform NEON: arsitektur 16 komponen berjenjang (Primitives, Blocks, Patterns) terinspirasi shadcn-vue, variabel token terstruktur, auto layout, varian, dan spesifikasi handoff.",description_en:"A unified design system for the NEON platform: 16 tiered components (Primitives, Blocks, Patterns) inspired by shadcn-vue, structured token variables, auto layout, component variants, and handoff specs.",longDescription:`Selama menjalani program magang sebagai <strong>Design System Lead & UI Designer</strong> di <strong>PT Vortex Buana Edumedia</strong> selama 3 minggu, saya merancang dan membangun fondasi <strong>NEON Design System</strong>. Sistem ini dibuat untuk mengatasi tantangan inkonsistensi antarmuka visual, redundansi komponen berulang, serta friksi handoff antara tim desain dan developer.

Dengan mengambil referensi arsitektur modern dari <strong>shadcn-vue</strong>, sistem ini dibangun secara modular mencakup kurang lebih <strong>16 komponen</strong> yang dibagi ke dalam 3 hierarki: <em>Primitive Elements</em>, <em>Blocks</em>, dan <em>Patterns</em>. Setiap komponen dioptimasi menggunakan auto layout responsif, variabel token semantik, component properties, serta dokumentasi spesifikasi desain yang siap diimplementasikan oleh tim frontend.`,longDescription_en:`During my 3-week apprenticeship as <strong>Design System Lead & UI Designer</strong> at <strong>PT Vortex Buana Edumedia</strong>, I architected and built the foundational <strong>NEON Design System</strong>. This system resolved interface inconsistencies, redundant design debt, and developer handoff friction across product teams.

Drawing architectural inspiration from <strong>shadcn-vue</strong>, the system is organized modularly into approximately <strong>16 components</strong> across 3 tiers: <em>Primitive Elements</em>, <em>Blocks</em>, and <em>Patterns</em>. Every component is engineered with responsive auto layout, semantic token variables, comprehensive component properties, and production-ready design specifications.`,sections:[{id:"overview",navTitle:"Overview",navTitle_en:"Overview",title:"Project Overview",title_en:"Project Overview",subtitle:"Membangun fondasi sistem desain modular berjenjang dalam waktu 3 minggu.",subtitle_en:"Architecting a tiered, modular design system within a 3-week delivery timeframe.",blocks:[{type:"text",lead:!0,content:"NEON Design System dirancang untuk menyatukan standar antarmuka seluruh produk digital di <strong>PT Vortex Buana Edumedia</strong>. Dalam proyek 3 minggu ini, fokus diarahkan pada pembuatan 16 komponen utama yang dapat diskalakan, mulai dari elemen paling atomik hingga pola interaksi kompleks.",content_en:"NEON Design System unifies visual and functional standards across digital platforms at <strong>PT Vortex Buana Edumedia</strong>. Executed over a 3-week timeline, the project delivered 16 core scalable components, bridging atomic primitives to complex interface patterns."},{type:"features_grid",title:"Core Deliverables & Highlights",title_en:"Core Deliverables & Highlights",features:[{title:"16 Reusable Components",desc:"Perpustakaan komponen UI lengkap dengan varian state (default, hover, active, disabled)."},{title:"3-Tier Architecture",desc:"Pengelompokan sistematis: Primitive Elements, Blocks, dan Patterns."},{title:"shadcn-vue Inspired",desc:"Pendekatan modular, accessible, dan komposabilitas tinggi yang ramah developer."},{title:"Semantic Variables & Tokens",desc:"Skala warna, radius sudut, dan spasi 4px grid yang tersentralisasi."},{title:"Dev-Ready Specs",desc:"Dokumentasi redline, padding, toleransi layout, dan checklist Design QA."}],features_en:[{title:"16 Reusable Components",desc:"Comprehensive UI component library with multi-state variants (default, hover, active, disabled)."},{title:"3-Tier Architecture",desc:"Structured taxonomy: Primitive Elements, Blocks, and Patterns."},{title:"shadcn-vue Inspired",desc:"Composable, accessible, and developer-friendly architecture."},{title:"Semantic Variables & Tokens",desc:"Centralized color tokens, corner radii, and 4px-grid spacing rules."},{title:"Dev-Ready Specs",desc:"Precise redlines, layout tolerances, padding guides, and Design QA guidelines."}]}]},{id:"background",navTitle:"Background",navTitle_en:"Background",title:"Background & Architectural Reference",title_en:"Background & Architectural Reference",subtitle:"Alasan dibuatnya sistem dan adopsi filosofi desain modern shadcn-vue.",subtitle_en:"Why the system was necessary and how modern design patterns were adopted.",blocks:[{type:"text",content:`Sebelum sistem ini dibuat, perancangan antarmuka menghadapi kendala klasik: duplikasi elemen tombol dan input di berbagai file terpisah, inkonsistensi spasi dan warna, serta pertanyaan berulang saat serah terima desain ke developer.

Untuk menyelesaikannya, saya mengadopsi filosofi <strong>shadcn-vue</strong>. Berbeda dengan library tradisional yang kaku, shadcn-vue menekankan pada <em>prinsip komposisi (composability)</em>: komponen dasar yang fleksibel, tidak membatasi developer, dan memiliki struktur semantik yang jelas untuk aksesibilitas.`,content_en:`Prior to this design system, product teams faced interface fragmentation: duplicate buttons and inputs across detached files, mismatched padding and hex values, and handoff friction.

To address this sustainably, I adapted principles from <strong>shadcn-vue</strong>. Rather than creating a rigid black-box library, shadcn-vue champions <em>composability</em>: providing highly flexible primitives with accessible markup that developers can easily extend and customize.`},{type:"image",src:S,caption:"Eksplorasi ragam komponen & pola antarmuka NEON Design System",caption_en:"Exploration of varied components and interface patterns in NEON Design System"}]},{id:"component-tiers",navTitle:"3-Tier System",navTitle_en:"3-Tier System",title:"Component Taxonomy: 3 Tiers, 16 Components",title_en:"Component Taxonomy: 3 Tiers, 16 Components",subtitle:"Hierarki terstruktur dari fondasi primitif hingga pola halaman.",subtitle_en:"Structured hierarchy from atomic primitives to layout patterns.",blocks:[{type:"text",content:"Ke-16 komponen yang dirancang dalam waktu 3 minggu ini dibagi ke dalam 3 tingkatan (tiers) agar tim memiliki panduan jelas kapan harus menggunakan elemen dasar atau merangkainya menjadi pola yang lebih besar:",content_en:"The 16 components crafted during the 3-week sprint are categorized into 3 distinct tiers to guide designers and engineers on proper composition:"},{type:"features_grid",title:"Taxonomy Breakdown",title_en:"Taxonomy Breakdown",features:[{title:"Tier 1: Primitive Elements",desc:"Fondasi atomik terkecil: Buttons, Badges, Chips/Tags, Typography scales, Icon containers, dan Bubble element."},{title:"Tier 2: Blocks",desc:"Kombinasi primitif menjadi blok fungsional: Input Field with validation, Search Bar, Card Containers, dan Dropdown Select."},{title:"Tier 3: Patterns",desc:"Pola interaksi level tinggi: Filter Toolbar, Modal / Dialog Boxes, Question Bank Collection Card, dan Navigation Rails."}],features_en:[{title:"Tier 1: Primitive Elements",desc:"Foundational atoms: Buttons, Badges, Chips/Tags, Typography scales, Icon containers, and the Bubble element."},{title:"Tier 2: Blocks",desc:"Composable functional blocks: Form Input Fields with validation states, Search Bar, Card Containers, and Dropdown Select."},{title:"Tier 3: Patterns",desc:"High-level interface flows: Filter Toolbar, Dialog/Modal Overlays, Question Bank Cards, and Navigation Rails."}]}]},{id:"auto-layout",navTitle:"Auto Layout",navTitle_en:"Auto Layout",title:"Engineering Craft I: Auto Layout & Resizing Rules",title_en:"Engineering Craft I: Auto Layout & Resizing Rules",subtitle:"Penerapan Auto Layout presisi untuk perilaku responsif nyata pada komponen Bubble.",subtitle_en:"Precision Auto Layout implementation mirroring actual CSS flexbox on the Bubble component.",blocks:[{type:"text",content:`Setiap komponen dibangun secara disiplin menggunakan <strong>Figma Auto Layout</strong>. Sebagai contoh implementasi pada komponen <strong>Bubble</strong>, komponen ini dirancang dengan aturan horizontal & vertical padding yang seimbang, gap antar-ikon yang konsisten, serta konfigurasi <em>Hug Contents</em> agar lebar beradaptasi alami terhadap panjang teks label.

Komponen induk (Blocks & Patterns) menerapkan prinsip <em>Fill Container</em> dan min/max width agar langsung siap merespons berbagai ukuran breakpoint layar desktop maupun mobile.`,content_en:`Every component strictly utilizes <strong>Figma Auto Layout</strong> to mirror production CSS flexbox behavior. Taking the <strong>Bubble</strong> component as a core case study, it was engineered with balanced horizontal and vertical padding, uniform icon gaps, and <em>Hug Contents</em> resizing so tags flow fluidly based on text length.

Parent blocks and patterns utilize <em>Fill Container</em> and min/max width constraints to guarantee responsive integrity across mobile and desktop breakpoints.`},{type:"images_grid",columns:2,caption:"Bukti penerapan Auto Layout pada komponen Bubble: konfigurasi frame, padding, dan hierarki layer",caption_en:"Proof of Auto Layout implementation on Bubble component: frame configs, padding, and layer hierarchy",images:[{src:f,caption:"Auto Layout Frame Configuration & Padding"},{src:I,caption:"Auto Layout Alignment & Constraint Details"}]}]},{id:"tokens-variables",navTitle:"Variables & Tokens",navTitle_en:"Variables & Tokens",title:"Engineering Craft II: Figma Variables & Design Tokens",title_en:"Engineering Craft II: Figma Variables & Design Tokens",subtitle:"Standarisasi token semantik warna, radius sudut, dan spasi.",subtitle_en:"Standardizing semantic color, radius, and spacing tokens.",blocks:[{type:"text",content:`Sistem token dibangun bertingkat menggunakan fitur <strong>Figma Variables</strong>:

1. <strong>Global Primitives</strong>: Palet warna dasar netral, brand blue, success green, danger red.
2. <strong>Semantic Aliases</strong>: Variabel kontekstual seperti <code>surface-primary</code>, <code>text-muted</code>, <code>border-interactive</code>, dan <code>focus-ring</code>.
3. <strong>Spacing & Radius</strong>: Spasi berbasis grid 4px (4, 8, 12, 16, 24, 32px) dan skala radius (sm: 4px, md: 8px, full: 9999px untuk Bubble).

Dengan arsitektur variabel ini, penggantian tema (light/dark) atau pembaruan branding dapat dilakukan dalam hitungan detik tanpa merusak struktur komponen.`,content_en:`Tokens are architected systematically through <strong>Figma Variables</strong>:

1. <strong>Global Primitives</strong>: Raw color scales (neutral shades, brand blue, success green, danger red).
2. <strong>Semantic Aliases</strong>: Functional context tokens like <code>surface-primary</code>, <code>text-muted</code>, <code>border-interactive</code>, and <code>focus-ring</code>.
3. <strong>Spacing & Corner Radii</strong>: 4px-grid system (4, 8, 12, 16, 24, 32px) and semantic radii (sm: 4px, md: 8px, full: 9999px for Bubble pills).

This architecture empowers effortless theme-switching (light/dark) and seamless brand updates without breaking design files.`},{type:"image",src:v,caption:"Dokumentasi & Panel Figma Variables: Pengelolaan token warna, spasi, dan nilai semantik terpusat",caption_en:"Figma Variables panel: centralized color tokens, spacing scales, and semantic definitions"}]},{id:"component-props",navTitle:"Properties & States",navTitle_en:"Properties & States",title:"Engineering Craft III: Properties, Variants & Interactive States",title_en:"Engineering Craft III: Properties, Variants & Interactive States",subtitle:"Struktur varian bersih dengan Boolean toggle dan Text props.",subtitle_en:"Clean variant matrices powered by Boolean toggles and Text props.",blocks:[{type:"text",content:`Untuk mencegah duplikasi frame yang membingungkan desainer, saya memanfaatkan <strong>Figma Component Properties</strong> secara maksimal:

- <strong>Variant Dimensions</strong>: Ukuran (Small, Medium, Large) dan Jenis (Solid, Outline, Ghost, Soft).
- <strong>Interactive States</strong>: Pemetaan state lengkap (<em>Default, Hover, Active/Pressed, Focused, Disabled</em>).
- <strong>Boolean Toggles</strong>: Properti <code>showLeftIcon</code>, <code>showRightIcon</code>, <code>isRemovable</code>.
- <strong>Instance Swap & Text Props</strong>: Memungkinkan penggantian ikon dan pengubahan label teks langsung dari panel properti samping tanpa harus mendouble-click layer di canvas.`,content_en:`To eliminate visual clutter and component explosion, I leveraged <strong>Figma Component Properties</strong> across all 16 components:

- <strong>Variant Matrix</strong>: Dimensions (Small, Medium, Large) x Visual styles (Solid, Outline, Ghost, Soft).
- <strong>Interactive States</strong>: Fully modeled states (<em>Default, Hover, Active/Pressed, Focused, Disabled</em>).
- <strong>Boolean Toggles</strong>: <code>showLeftIcon</code>, <code>showRightIcon</code>, <code>isRemovable</code>.
- <strong>Instance Swap & Text Props</strong>: Designers can customize icon glyphs and text values directly from the Figma sidebar without diving into canvas layers.`},{type:"image",src:C,caption:"Component Properties & Varian Matrix: Panel konfigurasi props, boolean switches, dan state variants",caption_en:"Component Properties & Variant Matrix: Props configuration panel, boolean toggles, and state variants"}]},{id:"design-specs",navTitle:"Design Specs",navTitle_en:"Design Specs",title:"Design Specs & Developer Handoff",title_en:"Design Specs & Developer Handoff",subtitle:"Spesifikasi ukuran piksel presisi dan panduan inspeksi Dev Mode.",subtitle_en:"Pixel-precise redlines, token mappings, and Dev Mode handoff guidelines.",blocks:[{type:"text",content:`Jembatan antara desain dan rekayasa kode dibangun melalui dokumentasi spesifikasi yang ketat:

- <strong>Redline Measurements</strong>: Nilai padding internal, line-height teks, ketebalan border, dan bounding box eksplisit.
- <strong>Token Translation Map</strong>: Setiap nilai visual di Figma dipetakan 1:1 ke nama utility class Tailwind CSS atau variabel SCSS/CSS.
- <strong>Accessibility Checklist</strong>: Seluruh kombinasi warna latar dan teks diverifikasi memenuhi standar rasio kontras <strong>WCAG 2.1 AA</strong> (minimal 4.5:1 untuk teks normal).
- <strong>Figma Dev Mode Ready</strong>: Komponen diorganisir dengan penamaan layer bersih agar developer dapat meng-copy kode snippet secara instan.`,content_en:`Bridging design and engineering requires rigorous specification:

- <strong>Redline Measurements</strong>: Explicit internal padding, font line-heights, border widths, and bounding boxes.
- <strong>Token Translation Map</strong>: Every Figma value maps 1:1 to Tailwind CSS classes or CSS variables.
- <strong>Accessibility Validation</strong>: All foreground/background color pairings achieve <strong>WCAG 2.1 AA</strong> contrast (minimum 4.5:1 for standard text).
- <strong>Figma Dev Mode Ready</strong>: Clean layer naming and property structure allows engineers to copy ready-to-use CSS/Vue code snippets immediately.`},{type:"images_grid",columns:2,caption:"Dokumentasi spesifikasi desain (Design Specs): ukuran, padding, variasi state, dan redlines pengembang",caption_en:"Design specifications documentation: measurements, padding, state variations, and developer redlines",images:[{src:w,caption:"Design Specs 01: Component Dimensions & Spacing"},{src:T,caption:"Design Specs 02: Typography & Alignment Specs"},{src:B,caption:"Design Specs 03: Interactive State Padding"},{src:M,caption:"Design Specs 04: Border & Radius Values"}]}]},{id:"reusability-impact",navTitle:"Reusability & Impact",navTitle_en:"Reusability & Impact",title:"Reusability in Action & Future Scalability",title_en:"Reusability in Action & Future Scalability",subtitle:"Dirancang sebagai fondasi multi-platform untuk seluruh produk web dan mobile ke depan.",subtitle_en:"Architected as a multi-platform foundation for all future web and mobile products.",blocks:[{type:"text",content:`Komponen yang dirancang dalam <strong>NEON Design System</strong> tidak ditujukan untuk satu fitur tunggal, melainkan dibangun sebagai <em>Single Source of Truth</em> yang agnostik platform. Spesimen implementasi (seperti komponen Bubble di bawah) mendemonstrasikan bagaimana komponen ini siap langsung dikomposisikan ke dalam berbagai modul produk digital di PT Vortex Buana Edumedia—baik portal web responsif, modul latihan, dashboard pengajar, maupun aplikasi mobile siswa.

<strong>Dampak Utama Sistem:</strong>
1. <strong>Fondasi Multi-Platform</strong>: Arsitektur token dan komponen modular siap digunakan bersama di web (Vue/Tailwind) maupun aplikasi mobile di masa mendatang.
2. <strong>Kecepatan Eksplorasi (Design Velocity)</strong>: Tim produk dapat merangkai alur baru dengan cepat tanpa harus mendesain ulang komponen dasar dari awal.
3. <strong>Efisiensi Kolaborasi & Handoff</strong>: Mengeliminasi friksi antara desainer dan programmer berkat penamaan token dan spesifikasi yang seragam.`,content_en:`The components crafted in the <strong>NEON Design System</strong> are not constrained to a single application; they are architected as a platform-agnostic <em>Single Source of Truth</em>. The implementation specimen below (demonstrated through the Bubble component) illustrates how these components seamlessly integrate into future digital product suites at PT Vortex Buana Edumedia—spanning responsive web portals, assessment dashboards, and mobile applications.

<strong>Key Outcomes & Strategic Value:</strong>
1. <strong>Multi-Platform Scalability</strong>: Tokenized foundations and modular components readily map to web environments (Vue/Tailwind) and upcoming mobile applications.
2. <strong>Design Velocity</strong>: Product teams can rapidly compose new features using battle-tested components without reinventing foundational atoms.
3. <strong>Seamless Handoff Alignment</strong>: Drastically reduces design-to-code discrepancies through unified variable names, consistent padding, and clear states.`},{type:"image",src:A,caption:"Spesimen penerapan nyata: Contoh fleksibilitas komponen Bubble saat diintegrasikan ke dalam antarmuka modul produk",caption_en:"Real-world implementation specimen: Demonstrating Bubble component flexibility when composed into product module interfaces"}]}]},x="/assets/cover-DUqbh8G9.webp",u="/assets/app-BjXXcBUM.webp",U={title:"Vitacal App – Aplikasi Kesehatan (Beta Test)",title_en:"Vitacal App – Health & Nutrition Tracker (Beta Test)",slug:"vitacal-app-aplikasi-kesehatan",statusBadge:"Beta Test",statusBadge_en:"Beta Test",roles:["UI/UX Designer","Frontend Developer","Backend Developer"],roles_en:["UI/UX Designer","Frontend Developer","Backend Developer"],isActive:!0,gallery:[u,u,u],description:"Aplikasi mobile penghitung kalori dan analisis nutrisi personal menggunakan algoritma Mifflin-St Jeor, terintegrasi Open Food Facts API dan dataset Kaggle.",description_en:"A mobile app for daily calorie calculation and personal nutritional analysis using the Mifflin-St Jeor algorithm, integrated with Open Food Facts API and Kaggle datasets.",longDescription:"Vitacal App adalah aplikasi mobile kesehatan yang membantu pengguna memahami kebutuhan kalori harian mereka secara lebih akurat dan personal. Aplikasi ini menggunakan algoritma Mifflin-St Jeor untuk menghitung BMR, BMI, serta memberikan rekomendasi dan analisis kalori berdasarkan data pribadi pengguna. Proyek ini dikembangkan mulai dari riset UI/UX di Figma, hingga implementasi Frontend menggunakan Flutter dan Backend dengan Flask serta PostgreSQL. Untuk memperkaya fungsionalitas, data pencarian makanan diambil dari dataset publik Kaggle, dan fitur pemindai barcode makanan diintegrasikan langsung dengan Open Food Facts API. Sistem autentikasi menggunakan OTP via Fonnte API untuk akses yang cepat. Fokus utama proyek ini adalah menghadirkan alat pemantau nutrisi yang kompleks secara data teknis, namun tetap memiliki antarmuka yang sangat sederhana digunakan.",imageSrc:x,techTags:["Flutter","Flask","PostgreSQL","Mifflin Algorithm","Open Food Facts API","Kaggle Dataset","Fonnte API","Figma"],timeline:"2025 - 2026",platform:"Mobile Application",platform_en:"Mobile Application",context:"Final Academic Project / Tugas Akhir",context_en:"Final Academic Project / Graduation Thesis",theChallenge:"Memahami asupan kalori harian dan menjaga berat badan ideal merupakan tantangan bagi banyak orang. Sayangnya, banyak aplikasi pencatat kalori di pasaran memiliki antarmuka yang terlalu rumit dan database makanan yang terbatas. Pengguna sering kali merasa kesulitan dan kehilangan motivasi saat harus memasukkan data makanan kemasan yang mereka konsumsi sehari-hari secara manual.",theChallenge_en:"Understanding daily calorie intake and maintaining an ideal weight is a challenge for many. Unfortunately, many calorie tracking apps on the market have interfaces that are too complex and food databases that are too limited. Users often struggle and lose motivation when they have to manually log packaged foods they consume daily.",theSolution:"Pendekatan Vitacal App berfokus pada personalisasi pengguna dan kemudahan input data. Mengandalkan algoritma <strong>Mifflin-St Jeor</strong> yang teruji klinis, aplikasi membagi sistem menjadi Frontend Flutter yang responsif dan Backend Flask. Untuk mengatasi hambatan pencatatan, sistem menarik data dari dataset publik Kaggle untuk pencarian makanan lokal, dan mengintegrasikan Open Food Facts API agar pengguna cukup melakukan scan barcode pada makanan kemasan tanpa harus mengetik manual.",theSolution_en:"The Vitacal App approach focuses on user personalization and ease of data entry. Relying on the clinically proven <strong>Mifflin-St Jeor</strong> algorithm, the app splits the system into a responsive Flutter frontend and a Flask backend. To address logging friction, the system pulls data from a public Kaggle dataset for local food searches, and integrates the Open Food Facts API so users can simply scan barcodes on packaged foods instead of typing manually.",keyFeatures:[{title:"Personalisasi & Analisis Kalori",desc:"Menghitung batas kalori harian, BMI, dan analisis riwayat berat badan secara personal dan presisi menggunakan algoritma Mifflin."},{title:"Smart Barcode Scanner",desc:"Integrasi dengan Open Food Facts API untuk mengenali dan melacak nutrisi makanan kemasan secara instan hanya dengan memindai barcode."},{title:"Pencarian Makanan Komprehensif",desc:"Database pencarian makanan yang kaya dan akurat, diolah langsung dari dataset nutrisi publik Kaggle."},{title:"Otentikasi OTP WhatsApp",desc:"Sistem login dan registrasi yang mulus, aman, dan tanpa password menggunakan nomor WhatsApp melalui integrasi Fonnte API."}],keyFeatures_en:[{title:"Personalization & Calorie Analysis",desc:"Calculates daily calorie limits, BMI, and analyzes weight history precisely using the Mifflin algorithm."},{title:"Smart Barcode Scanner",desc:"Integration with the Open Food Facts API to instantly identify and track packaged food nutrition by scanning barcodes."},{title:"Comprehensive Food Search",desc:"Rich and accurate food search database, processed directly from Kaggle public nutrition datasets."},{title:"WhatsApp OTP Authentication",desc:"Seamless, secure, passwordless registration and login using WhatsApp numbers integrated via Fonnte API."}],theImpact:"Aplikasi ini berhasil menghadirkan solusi pemantauan gizi yang sangat praktis. Integrasi API pihak ketiga (Kaggle & Open Food Facts) secara signifikan memangkas waktu proses logging makanan bagi pengguna, menjadikan aplikasi ini tidak sekadar prototipe teoretis, melainkan produk fungsional yang siap memecahkan masalah diet di dunia nyata.",theImpact_en:"This application successfully delivers a highly practical nutritional monitoring solution. Third-party API integrations (Kaggle & Open Food Facts) significantly reduced food logging time for users, making the app not just a theoretical prototype, but a functional product ready to solve real-world dietary challenges.",githubUrl:"https://github.com/ariyoaziz/vitacal_app",figmaUrl:"https://www.figma.com/design/tZ7gIP7n7iDnZDou6iIULJ/%F0%9F%8E%A8-VitaCal.V2---Product-Design---System?node-id=0-1&t=efbqF6bJpZGey44Z-1",figmaEmbedUrl:"https://embed.figma.com/design/tZ7gIP7n7iDnZDou6iIULJ/%F0%9F%8E%A8-VitaCal.V2---Product-Design---System?node-id=0-1&embed-host=share"},_="/assets/cover-CxTBtQb_.webp",j={title:"FrameFlow – Solusi Proofing Foto Modern (Beta Test)",title_en:"FrameFlow – Modern Photo Proofing Solution (Beta Test)",slug:"frameflow",statusBadge:"Beta Test",statusBadge_en:"Beta Test",isActive:!0,roles:["UI/UX Designer","Frontend Developer"],roles_en:["UI/UX Designer","Frontend Developer"],description:"Platform delivery foto instan yang mengintegrasikan Google Drive dan WhatsApp untuk mempermudah klien memilih foto favorit tanpa ribet.",description_en:"An instant photo delivery platform integrating Google Drive and WhatsApp to simplify the photo selection process for clients.",longDescription:"FrameFlow adalah solusi proofing foto modern yang dirancang khusus untuk fotografer (Wedding, Portrait, Event, Commercial). Aplikasi ini mempercepat proses pengiriman foto ke klien. Cukup hubungkan Google Drive, buat galeri dalam hitungan detik, dan biarkan klien memilih foto favorit mereka secara interaktif. Hasil pilihan klien akan otomatis dikirimkan ke WhatsApp Anda, menghilangkan keribetan dan miskomunikasi dalam proses seleksi foto. Proyek ini masih dalam tahap beta test.",longDescription_en:"FrameFlow is a modern photo proofing solution designed specifically for photographers (Wedding, Portrait, Event, Commercial). This app speeds up the photo delivery process to clients. Simply connect Google Drive, create a gallery in seconds, and let clients choose their favorite photos interactively. The client's selections will automatically be sent to your WhatsApp, eliminating hassle and miscommunication in the photo selection process. This project is currently in the beta test stage.",imageSrc:_,techTags:["Frontend","Web App","UI/UX Design","Beta Test"],timeline:"2025",timeline_en:"2025",platform:"Web Application",platform_en:"Web Application",context:"Personal Project / Eksplorasi Frontend",context_en:"Personal Project / Frontend Exploration",projectUrl:"https://frameflow.berworkshed.workers.dev/"},N="/assets/cover-BmuJrqyp.webp",E={title:"Berworkshed – Digital Product & Creative Workshop",title_en:"Berworkshed – Digital Product & Creative Workshop",slug:"berworkshed",isActive:!0,isBuilding:!0,statusBadge:"Building",statusBadge_en:"Building",roles:["Founder","Product Designer","Developer"],roles_en:["Founder","Product Designer","Developer"],description:"Inisiatif studio mandiri dan bengkel kerja kreatif yang sedang dibangun untuk merancang solusi digital, produk web interaktif, dan eksplorasi desain terapan.",description_en:"An independent studio initiative and creative workshop currently being built to craft digital solutions, interactive web products, and applied design explorations.",longDescription:"Berworkshed adalah inisiatif studio mandiri dan wadah eksplorasi kreatif yang berfokus pada desain produk digital, rekayasa frontend modern, dan perancangan pengalaman pengguna yang berkarakter. Proyek ini dibangun dari nol sebagai laboratorium kerja untuk melahirkan produk-produk mandiri yang menyelesaikan kebutuhan nyata, mulai dari tool produktivitas, antarmuka web interaktif, hingga visual branding. Saat ini Berworkshed sedang dalam tahap pembangunan fondasi, standarisasi sistem komponen, dan pengembangan portofolio produk perdana.",longDescription_en:"Berworkshed is an independent studio initiative and creative workshop space focusing on digital product design, modern frontend engineering, and distinctive user experience craftsmanship. Built from the ground up as a working laboratory, it aims to create standalone products that solve real user needs—spanning productivity tools, interactive web interfaces, and visual branding. Currently in active development, focusing on component system standardization and inaugural product builds.",imageSrc:N,techTags:["Building","Product Design","Creative Studio","Frontend","UI/UX Design"],timeline:"2026 – Sekarang",timeline_en:"2026 – Present",platform:"Digital Studio / Lab",platform_en:"Digital Studio / Lab",context:"Independent Venture / Building in Public",context_en:"Independent Venture / Building in Public",projectUrl:"https://ber.berworkshed.workers.dev/"},D="/assets/cover-B3t3S3rK.webp",L={title:"CV Builder",title_en:"CV Builder",slug:"cv-builder",statusBadge:"Web App",statusBadge_en:"Web App",roles:["Product Designer","Frontend Developer"],roles_en:["Product Designer","Frontend Developer"],isActive:!0,description:"CV Builder adalah aplikasi web client-side untuk membuat CV profesional yang terstruktur, ramah ATS, responsif, dan siap dicetak atau disimpan sebagai PDF langsung dari browser.",description_en:"CV Builder is a client-side web application for creating structured, ATS-friendly, responsive CVs that can be printed or saved as PDF directly from the browser.",longDescription:"CV Builder dirancang untuk membantu pengguna membuat CV profesional dengan proses yang cepat, terstruktur, dan tetap fleksibel. Aplikasi ini berjalan sepenuhnya di sisi client, sehingga pengguna dapat mengedit CV tanpa akun dan tanpa database. Editor CV menggunakan section yang terstruktur, menyediakan template Modern, Minimal, dan Classic, serta menampilkan preview real-time dengan format kertas A4. CV dapat langsung dicetak atau disimpan sebagai PDF melalui fitur bawaan browser. Pengguna juga dapat mengimpor dan mengekspor data CV dalam format JSON agar data mudah dipindahkan dan dicadangkan. Dukungan bahasa Indonesia dan Inggris, tampilan yang responsif untuk desktop, tablet, dan mobile, security headers, optimasi static assets, serta metadata Open Graph melengkapi pengalaman aplikasi. Untuk membantu penulisan, aplikasi menyediakan prompt AI eksternal yang dapat digunakan secara manual untuk membuat atau memperbaiki isi CV, kemudian hasil JSON-nya dapat diimpor kembali ke aplikasi. Seluruh data utama disimpan di browser menggunakan localStorage dan tidak dikirim ke server secara otomatis. Source code dikembangkan di repository privat CV-Builder-Raw, disanitasi melalui GitHub Actions ke repository publik CV-Builder, lalu dideploy sebagai static export Next.js dengan output folder out menggunakan Cloudflare Workers Static Assets ke website production cv-builder.weareaap.workers.dev.",longDescription_en:"CV Builder is designed to help users create professional CVs through a fast, structured, and flexible workflow. The application runs entirely on the client side, allowing users to edit their CV without an account or database. Its structured editor includes Modern, Minimal, and Classic templates, along with a real-time A4 paper preview. CVs can be printed or saved as PDF directly through the browser. Users can also import and export CV data as JSON for easy transfer and backup. Indonesian and English language support, responsive layouts for desktop, tablet, and mobile, security headers, static asset optimization, and Open Graph metadata complete the experience. For writing assistance, the app provides external AI prompts that can be used manually to create or improve CV content, after which the resulting JSON can be imported back into the application. All primary data is stored in the browser using localStorage and is not sent to a server automatically. Source code is developed in the private CV-Builder-Raw repository, sanitized through GitHub Actions into the public CV-Builder repository, then deployed as a Next.js static export with the out output folder using Cloudflare Workers Static Assets at cv-builder.weareaap.workers.dev.",keyFeatures:[{title:"Editor CV Terstruktur",desc:"Menyusun isi CV melalui section yang jelas agar informasi mudah dikelola dan tetap ramah ATS."},{title:"Tiga Template Visual",desc:"Pilih template Modern, Minimal, atau Classic sesuai kebutuhan dan karakter profesional."},{title:"Preview A4 dan PDF",desc:"Melihat perubahan secara real-time dalam format A4, lalu mencetak atau menyimpan CV sebagai PDF langsung dari browser."},{title:"Import dan Export JSON",desc:"Memindahkan, mencadangkan, dan memulihkan data CV menggunakan format JSON."},{title:"Penyimpanan Lokal",desc:"Data utama disimpan di localStorage tanpa akun dan tanpa database, sehingga tetap berada di browser pengguna."},{title:"Prompt AI Eksternal",desc:"Membantu membuat atau memperbaiki isi CV melalui layanan AI eksternal secara manual, kemudian mengimpor hasil JSON kembali ke aplikasi."},{title:"Bilingual dan Responsif",desc:"Mendukung bahasa Indonesia dan Inggris serta nyaman digunakan di desktop, tablet, dan mobile."},{title:"Static Deployment",desc:"Dibangun sebagai static export Next.js dengan output out dan dideploy melalui Cloudflare Workers Static Assets."}],keyFeatures_en:[{title:"Structured CV Editor",desc:"Organize CV content into clear sections so information stays easy to manage and ATS-friendly."},{title:"Three Visual Templates",desc:"Choose Modern, Minimal, or Classic templates based on your needs and professional style."},{title:"A4 Preview and PDF",desc:"See changes in real time on an A4 layout, then print or save the CV as PDF directly from the browser."},{title:"JSON Import and Export",desc:"Transfer, back up, and restore CV data using the JSON format."},{title:"Local Storage",desc:"Primary data is stored in localStorage without accounts or a database, keeping it in the user's browser."},{title:"External AI Prompts",desc:"Create or improve CV content through an external AI service manually, then import the resulting JSON back into the app."},{title:"Bilingual and Responsive",desc:"Supports Indonesian and English and works comfortably on desktop, tablet, and mobile."},{title:"Static Deployment",desc:"Built as a Next.js static export with an out output folder and deployed through Cloudflare Workers Static Assets."}],imageSrc:D,gallery:[D],techTags:["Frontend","Next.js","React","TypeScript","Tailwind CSS","Radix UI","Zustand","React Hook Form","Zod","Lucide React","Sonner","date-fns","GitHub Actions","Cloudflare Workers","Static Export"],timeline:"2026",timeline_en:"2026",platform:"Web Application",platform_en:"Web Application",context:"Personal Product / Portfolio Project",context_en:"Personal Product / Portfolio Project",projectUrl:"https://cv-builder.weareaap.workers.dev"},W="/assets/cover-BOdbDh29.webp",Z={title:"UI/UX Redesign – Aplikasi LinkAja (Halaman Beranda)",title_en:"UI/UX Redesign – LinkAja App (Homepage)",slug:"ui-ux-redesign-aplikasi-linkaja-halaman-beranda",statusBadge:"Case Study",statusBadge_en:"Case Study",isActive:!1,roles:["UI/UX Designer"],roles_en:["UI/UX Designer"],description:"Redesain halaman beranda aplikasi LinkAja dengan fokus pada penyederhanaan antarmuka dan peningkatan navigasi pengguna.",description_en:"Redesign of the LinkAja app homepage focusing on interface simplification, logical feature grouping, and improved visual accessibility. Features a modern and clean style for better mobile navigation.",imageSrc:W,techTags:["UI/UX Design","Figma","Redesign","Mobile App"],timeline:"Dikerjakan waktu kuliah",timeline_en:"Developed during college",platform:"Design Concept / Figma",platform_en:"Design Concept / Figma",context:"Studi Kasus UI/UX",context_en:"UI/UX Case Study",projectUrl:"https://www.figma.com/proto/IDGtCHDIcpBGVSCdmmEieC/Desain-Ulang-APP-LInkAja?page-id=5%3A57&node-id=5-60&p=f&viewport=293%2C-18%2C1.28&t=tBMct1pVLikWEzHC-1&scaling=scale-down&content-scaling=fixed",theChallenge:"Aplikasi keuangan digital seringkali dipenuhi dengan puluhan fitur dan ikon promosi di halaman berandanya, membuat pengguna baru merasa kebingungan (<em>cognitive overload</em>) saat mencoba mencari fitur utama seperti transfer atau pembayaran.",theChallenge_en:"Digital financial apps are often packed with dozens of features and promotional icons on their homepage, causing new users to experience cognitive overload when trying to find main functions like transfers or payments.",theSolution:"Melalui proses riset desain, saya merancang ulang halaman beranda LinkAja di Figma. Saya mengelompokkan ikon berdasarkan kategori prioritas, memperbesar elemen navigasi utama, serta memberikan ruang kosong (<em>white space</em>) yang cukup agar tampilan terasa lebih bersih, modern, dan minimalis.",theSolution_en:"Through a design research process, I redesigned the LinkAja homepage in Figma. I grouped icons based on priority categories, enlarged the main navigation elements, and provided sufficient white space so that the layout feels cleaner, more modern, and minimalist.",keyFeatures:[{title:"Simplified Navigation",desc:"Mengurangi kekacauan visual dengan memprioritaskan fungsi utama aplikasi."},{title:"Modern Aesthetics",desc:"Pendekatan warna dan tipografi baru yang lebih menyegarkan mata pengguna."}],keyFeatures_en:[{title:"Simplified Navigation",desc:"Reduces visual clutter by prioritizing the app's core functionalities."},{title:"Modern Aesthetics",desc:"A refreshing new color and typography approach that is easier on the user's eyes."}],theImpact:"Desain ulang ini menghasilkan prototipe visual yang jauh lebih intuitif. Studi kasus ini membuktikan bahwa penyederhanaan antarmuka dapat secara drastis meningkatkan kenyamanan pengguna tanpa harus menghilangkan fungsionalitas bisnis dari aplikasi itu sendiri.",theImpact_en:"This redesign resulted in a significantly more intuitive visual prototype. This case study demonstrates that simplifying the interface can drastically improve user comfort without eliminating the business functionalities of the app itself."},V="/assets/cover-D4MADJYd.webp",z={title:"UI/UX Design – Website E-Commerce Alat Outdoor",title_en:"UI/UX Design – Outdoor Gear E-Commerce",slug:"ui-ux-design-website-e-commerce-alat-outdoor",statusBadge:"Case Study",statusBadge_en:"Case Study",isActive:!1,roles:["UI/UX Designer"],roles_en:["UI/UX Designer"],description:"Desain UI/UX untuk platform e-commerce perlengkapan outdoor dengan navigasi yang intuitif dan visual yang bersih.",description_en:"Interface design for an e-commerce platform selling outdoor gear such as tents, cooking equipment, and hiking clothes. Focuses on intuitive user experience.",imageSrc:V,techTags:["UI/UX Design","Figma","E-Commerce","Prototyping"],timeline:"Dikerjakan waktu kuliah",timeline_en:"Developed during college",platform:"Design Concept / Figma",platform_en:"Design Concept / Figma",context:"Latihan Eksplorasi Desain",context_en:"Design Exploration Practice",projectUrl:"https://www.figma.com/design/cQTRvW7zsCFRTWT30f5tHe/e-Com?node-id=0-1&t=kskOzYVPNCdrkweR-1",theChallenge:"Situs <em>e-commerce</em> seringkali penuh sesak dengan produk, filter, dan promosi yang membuat pengguna kebingungan mencari barang spesifik, terutama untuk produk <em>niche</em> seperti peralatan <em>outdoor</em> dan <em>hiking</em>.",theChallenge_en:"E-commerce websites are often cluttered with products, filters, and promotions that confuse users looking for specific items, especially for niche products like outdoor and hiking gear.",theSolution:"Saya memusatkan desain pada navigasi yang efisien (<em>frictionless navigation</em>). Proses penyaringan kategori (tenda, alat masak, pakaian) dibuat sangat menonjol. Saya menerapkan skema warna <em>earth-tone</em> yang selaras dengan tema alam bebas, serta memberikan ruang kosong yang luas (<em>clean UI</em>) di sekitar foto produk.",theSolution_en:"I focused the design on frictionless navigation. The category filtering process (tents, cooking gear, apparel) is highly emphasized. I applied an earth-toned color palette aligned with the outdoor theme, and provided ample white space around product photos for a clean UI.",keyFeatures:[{title:"Clean Layout",desc:"Fokus langsung pada produk berkualitas tinggi tanpa distraksi elemen berlebih."},{title:"Intuitive Filtering",desc:"Sistem filter dan pencarian yang disesuaikan dengan kebiasaan pendaki/petualang."}],keyFeatures_en:[{title:"Clean Layout",desc:"Direct focus on high-quality products without the distraction of excessive UI elements."},{title:"Intuitive Filtering",desc:"Filter and search systems customized to the habits of hikers/adventurers."}],theImpact:"Menghasilkan <em>mockup</em> UI beresolusi tinggi yang siap diserahkan (<em>hand-off</em>) kepada tim <em>frontend</em>. Desain ini membuktikan kemampuan saya merangkai antarmuka penjualan yang berorientasi pada konversi (<em>conversion-centric design</em>).",theImpact_en:"Delivered a high-fidelity UI mockup ready for hand-off to the frontend team. This design demonstrates my ability to create sales interfaces focused on conversion-centric design."},R="/assets/cover-BvjOOP68.webp",H={title:"UI/UX Design – Order Food App",title_en:"UI/UX Design – Order Food App",slug:"ui-ux-design-order-food-app",statusBadge:"Case Study",statusBadge_en:"Case Study",isActive:!1,roles:["UI/UX Designer"],roles_en:["UI/UX Designer"],description:"Konsep desain aplikasi pemesanan makanan dengan tampilan modern dan alur pemesanan yang sederhana.",description_en:"Food ordering app design concept with a clean and modern approach. Provides an easily navigable user experience.",imageSrc:R,techTags:["UI/UX Design","Figma","Mobile App","Prototype"],timeline:"Dikerjakan waktu kuliah",timeline_en:"Developed during college",platform:"Design Concept / Figma",platform_en:"Design Concept / Figma",context:"Personal Portfolio Design",context_en:"Personal Portfolio Design",projectUrl:"https://www.behance.net/gallery/210655317/order-food",theChallenge:"Membuat aplikasi pengantaran makanan mengharuskan kita memikirkan bagaimana pengguna bisa menemukan makanan favorit, memasukkan ke keranjang, dan melakukan <em>checkout</em> dalam jumlah ketukan (<em>taps</em>) seminimal mungkin.",theChallenge_en:"Creating a food delivery app requires thinking about how users can find their favorite food, add it to the cart, and complete checkout in as few taps as possible.",theSolution:"Desain aplikasi ini memprioritaskan fotografi makanan (<em>food imagery</em>) yang besar untuk menggugah selera pengguna. Alur pemesanan dirancang secara linier (satu arah) agar tidak membingungkan, dari halaman beranda, rincian menu, modifikasi pesanan (<em>add-ons</em>), hingga layar <em>checkout</em> akhir.",theSolution_en:"The design of this application prioritizes large food imagery to stimulate the user's appetite. The order flow is designed linearly (one-way) to avoid confusion, navigating smoothly from the homepage, menu details, order customizations (add-ons), to the final checkout screen.",keyFeatures:[{title:"Appetizing Visuals",desc:"Penataan UI yang menonjolkan visual gambar menu dengan tata letak bergaya modern."},{title:"Linear Checkout Flow",desc:"Alur pembelian yang sangat ringkas untuk mempercepat proses konversi pesanan."}],keyFeatures_en:[{title:"Appetizing Visuals",desc:"UI layout highlighting menu imagery with modern layout styles."},{title:"Linear Checkout Flow",desc:"A highly simplified buying flow to speed up the order conversion process."}],theImpact:"Konsep desain ini telah dipublikasikan di Behance dan mendapatkan apresiasi positif atas pendekatan minimalisnya yang tetap mempertahankan fungsionalitas utama aplikasi pesan antar.",theImpact_en:"This design concept was published on Behance and received positive feedback for its minimalist approach while retaining the core features of a food delivery application."},G="/assets/cover-C3v7gSjj.webp",Q={title:"UI/UX Design – Coffee App",title_en:"UI/UX Design – Coffee App",slug:"ui-ux-design-coffee-app",statusBadge:"Case Study",statusBadge_en:"Case Study",isActive:!1,roles:["UI/UX Designer"],roles_en:["UI/UX Designer"],description:"Desain antarmuka aplikasi pemesanan kopi dengan visual elegan dan alur pengguna yang sederhana.",description_en:"An elegant and modern coffee ordering app interface design, emphasizing user comfort. Designed using Figma.",imageSrc:G,techTags:["UI/UX Design","Figma","Mobile App","Product Design"],timeline:"Dikerjakan waktu kuliah",timeline_en:"Developed during college",platform:"Design Concept / Figma",platform_en:"Design Concept / Figma",context:"Personal Portfolio Design",context_en:"Personal Portfolio Design",projectUrl:"https://www.behance.net/gallery/210655381/coffee",theChallenge:"Aplikasi <em>coffee shop</em> membutuhkan sentuhan personalisasi yang kuat (seperti mengatur ukuran gelas, kadar gula, jenis susu, dan es) tanpa membuat tampilan pemesanan terasa mengintimidasi atau rumit layaknya formulir panjang.",theChallenge_en:"Coffee shop applications require a strong touch of personalization (such as adjusting cup sizes, sweetness, milk types, and ice) without making the ordering screen feel intimidating or cluttered like a long form.",theSolution:"Saya memecahkan masalah ini dengan pendekatan <em>card UI</em> dan <em>toggle buttons</em>. Pengguna dapat meracik kopi mereka melalui opsi visual yang menyenangkan secara interaktif. Skema warna yang digunakan didominasi oleh corak kopi elegan dan gaya minimalis yang mewah (<em>premium feel</em>).",theSolution_en:"I solved this problem using a card UI and toggle button approach. Users can customize their drinks interactively through pleasant visual choices. The color palette is dominated by elegant coffee shades and a luxurious minimalist styling for a premium feel.",keyFeatures:[{title:"Customization Interface",desc:"Antarmuka kustomisasi minuman (gula, es, susu) yang sangat mudah digunakan."},{title:"Premium Dark Theme",desc:"Skema warna elegan yang mencerminkan suasana kedai kopi berkelas."}],keyFeatures_en:[{title:"Customization Interface",desc:"Highly intuitive drink customization interface (sugar, ice, milk) with minimal steps."},{title:"Premium Dark Theme",desc:"An elegant color scheme reflecting the atmosphere of a classy coffee shop."}],theImpact:"Desain ini (yang juga dapat dilihat di portofolio Behance saya) merepresentasikan kapabilitas saya dalam memadukan keindahan visual estetis dengan pengalaman pengguna (<em>User Experience</em>) yang logis dan fungsional.",theImpact_en:"This design (which is also showcased on my Behance portfolio) represents my capability to blend aesthetic visual beauty with a logical, functional User Experience."},O=[P,F,U,j,E,L,Z,z,H,Q];export{O as a,y as b,D as c,N as d,_ as f,m as n,x as v};
